CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,group_id TEXT NOT NULL,seed TEXT NOT NULL,started_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS rounds (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,group_id TEXT NOT NULL,name TEXT NOT NULL,score INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS rounds_group_score ON rounds(group_id,score DESC);
